#!/usr/bin/env node
// STORE SHOTS, ONE COMMAND (T704; owner 2026-11-13: "store pictures should be an autogenerated thing"):
//   scripts/heavy.sh store-shots 30 -- node app/tools/store-shots/run.mjs [--out DIR] [--at 2026-11-13T12:00:00-07:00] [--site URL] [--reuse] [--web URL]
// (T1076) THE SITE is the tool's own: with no --site it builds a store-shots web export of this checkout (EXPO_PUBLIC_STORE_SHOTS=1,
// app/dist/web-store-shots) and serves it on a local port for the run (store-shots/site.mjs; its header says what is pinned and
// what is live). --reuse serves the export already there (no rebuild). An explicit --site must carry the store-shots marker or the
// run STOPS AT ONCE saying what to do instead (a deployed site, staging included, never has it). The build is heavy: use heavy.sh.
// Shoots the Play phone set (the 7 shots of store-shots.json) from that web export in headless Chrome (it needs no emulator or APK, so it is the same on any machine and takes a few minutes), frames
// them at 1080x1920, and puts the 7 PNGs in DIR (default app/dist/store-shots/play-phone). No other argument is needed.
// PINNED: the page's clock (default: noon B.C. time today; B.C. is on permanent -07:00), light theme, phone 360x640 @3, the
// first-run/walkthrough/in-season notices seeded as seen, the saved-spot seed, the waters named by URL (Vedder, Chilliwack),
// the Conditions camera (20 km scale). NOT pinned: the live feeds (gauge readings, the forecast, DFO salmon notices) and the
// site's release; they are CHECKED instead (store-shots/checks.mjs asserts each shot's content on the page BEFORE the capture:
// salmon above the game-fish calendar, the forecast on the chart, more than one part on the river...). A failed check = no shot,
// no frames, exit 1, and `report.json` in DIR says which scene failed and why. Nothing is shot blank or stale.
import fs from 'node:fs'; import path from 'node:path';
import { spawnSync } from 'node:child_process';

const HERE = path.dirname(new URL(import.meta.url).pathname), APP = path.resolve(HERE, '../..');
const args = process.argv.slice(2), val = (k, d) => (args.includes(k) ? args[args.indexOf(k) + 1] : d);
for (const a of args) if (a.startsWith('--') && !['--out', '--at', '--site', '--reuse', '--web'].includes(a)) throw new Error(`store-shots/run: unknown flag ${a} (flags: --out, --at, --site, --reuse, --web)`);
const OUT = path.resolve(val('--out', path.join(APP, 'dist/store-shots/play-phone')));
const SITE = val('--site', process.env.STORE_SHOTS_SITE ?? null);   // null = build and serve its own export (T1076)
const bcToday = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Vancouver', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const AT = val('--at', `${bcToday}T12:00:00-07:00`);
if (Number.isNaN(Date.parse(AT))) throw new Error(`store-shots/run: --at ${AT} is not a date`);

// (T319) the Play phone set: the list without the shots `only` other targets take; Play takes at most 8
const shots = JSON.parse(fs.readFileSync(path.join(APP, 'tools/store-shots.json'), 'utf8')).shots.filter((s) => !s.only || s.only.includes('play-phone'));
if (shots.length < 2 || shots.length > 8) throw new Error(`store-shots/run: Play takes 2-8 phone shots, the play-phone set in store-shots.json has ${shots.length}`);

// the working folder is DIR/work (raw captures, framed output, the play-shots report); DIR itself ends holding only the 7 shots + report.json
const WORK = path.join(OUT, 'work');
fs.rmSync(OUT, { recursive: true, force: true }); fs.mkdirSync(path.join(WORK, 'raw'), { recursive: true });
console.log(`store-shots/run: site ${SITE ?? 'its own store-shots export'}, clock pinned to ${AT}, light theme, phone 1080x1920, ${shots.length} shots -> ${OUT}`);
const env = { ...process.env, STORE_SHOTS_DIR: WORK, PIN_AT: AT }; delete env.STORE_SHOTS_SITE;
const r = spawnSync(process.execPath, [path.join(APP, 'tools/store-shots.mjs'), '--only', 'play-phone', '--theme', 'light', ...(SITE ? ['--site', SITE] : []), ...(args.includes('--reuse') ? ['--reuse'] : []), ...(val('--web', null) ? ['--web', val('--web', null)] : [])],
  { stdio: 'inherit', cwd: APP, env });
const readReport = () => { try { return JSON.parse(fs.readFileSync(path.join(WORK, 'raw/play-shots-report.json'), 'utf8')); } catch { return null; } };
const rep = readReport();
const fail = (why) => { fs.writeFileSync(path.join(OUT, 'report.json'), JSON.stringify({ ok: false, site: SITE, pinAt: AT, why, scenes: rep?.scenes ?? null, sources: rep?.sources ?? null, web: rep?.web ?? null }, null, 2) + '\n');
  console.error(`store-shots/run: FAILED, nothing delivered: ${why}\n` + Object.entries(rep?.scenes ?? {}).filter(([, v]) => v !== 'ok').map(([k, v]) => `  ${k}: ${v}`).join('\n') + `\n  (details: ${path.join(OUT, 'report.json')}; the captures that passed are in ${path.join(WORK, 'raw')})`); process.exit(1); };
if (r.status !== 0) fail(`store-shots.mjs exited ${r.status}`);

// the 7 framed shots, exactly 1080x1920
const framed = path.join(WORK, 'store/light/play-phone');
const png = (f) => { const b = fs.readFileSync(f); return [b.readUInt32BE(16), b.readUInt32BE(20)]; };
const want = shots.map((s, i) => `${String(i + 1).padStart(2, '0')}-${s.scene}.png`);
for (const f of want) {
  const p = path.join(framed, f);
  if (!fs.existsSync(p)) fail(`${f} was not made`);
  const [w, h] = png(p); if (w !== 1080 || h !== 1920) fail(`${f} is ${w}x${h}, Play's phone size here is 1080x1920`);
  fs.copyFileSync(p, path.join(OUT, f));
}
fs.writeFileSync(path.join(OUT, 'report.json'), JSON.stringify({ ok: true, site: SITE, pinAt: AT, files: want, scenes: rep?.scenes ?? null, sources: rep?.sources ?? null, web: rep?.web ?? null }, null, 2) + '\n');
console.log(`store-shots/run: ${want.length} shots in ${OUT}`);
